import gptpu_pkg::*;
import fp8_pkg::*;

// FP8 E4M3 arithmetic testbench.
// Verifies fp8_add / fp8_mul against reference vectors generated by the
// cycle-accurate emulator (sim/emulator/emulator.py). Reference values are
// committed in the stimulus table below (add_ref / mul_ref).
module tb_fp8;
  localparam int N = 20;
  logic [7:0] a_vec [0:N-1];
  logic [7:0] b_vec [0:N-1];
  logic [7:0] add_ref [0:N-1];
  logic [7:0] mul_ref [0:N-1];

  initial begin
    int fails = 0;

    a_vec[ 0] = 8'h7F; b_vec[ 0] = 8'h38; add_ref[ 0] = 8'hF8; mul_ref[ 0] = 8'hF8;
    a_vec[ 1] = 8'h38; b_vec[ 1] = 8'h7F; add_ref[ 1] = 8'hF8; mul_ref[ 1] = 8'hF8;
    a_vec[ 2] = 8'h38; b_vec[ 2] = 8'h7E; add_ref[ 2] = 8'hF8; mul_ref[ 2] = 8'hF8;
    a_vec[ 3] = 8'h28; b_vec[ 3] = 8'h97; add_ref[ 3] = 8'h26; mul_ref[ 3] = 8'h8E;
    a_vec[ 4] = 8'h28; b_vec[ 4] = 8'h20; add_ref[ 4] = 8'h2C; mul_ref[ 4] = 8'h10;
    a_vec[ 5] = 8'h20; b_vec[ 5] = 8'hA4; add_ref[ 5] = 8'h98; mul_ref[ 5] = 8'h90;
    a_vec[ 6] = 8'h92; b_vec[ 6] = 8'hA5; add_ref[ 6] = 8'hA7; mul_ref[ 6] = 8'h00;
    a_vec[ 7] = 8'h38; b_vec[ 7] = 8'h38; add_ref[ 7] = 8'h40; mul_ref[ 7] = 8'h38;
    a_vec[ 8] = 8'h00; b_vec[ 8] = 8'h78; add_ref[ 8] = 8'hF8; mul_ref[ 8] = 8'h00;
    a_vec[ 9] = 8'h28; b_vec[ 9] = 8'h28; add_ref[ 9] = 8'h30; mul_ref[ 9] = 8'h18;
    a_vec[10] = 8'h28; b_vec[10] = 8'h98; add_ref[10] = 8'h24; mul_ref[10] = 8'h88;
    a_vec[11] = 8'h78; b_vec[11] = 8'hF8; add_ref[11] = 8'hF8; mul_ref[11] = 8'hF8;
    a_vec[12] = 8'h00; b_vec[12] = 8'h80; add_ref[12] = 8'h00; mul_ref[12] = 8'h00;
    a_vec[13] = 8'h28; b_vec[13] = 8'h27; add_ref[13] = 8'h2F; mul_ref[13] = 8'h1E;
    a_vec[14] = 8'h07; b_vec[14] = 8'h07; add_ref[14] = 8'h06; mul_ref[14] = 8'h00;
    a_vec[15] = 8'h38; b_vec[15] = 8'h28; add_ref[15] = 8'h3A; mul_ref[15] = 8'h28;
    a_vec[16] = 8'h7E; b_vec[16] = 8'h7F; add_ref[16] = 8'hF8; mul_ref[16] = 8'hF8;
    a_vec[17] = 8'h28; b_vec[17] = 8'h30; add_ref[17] = 8'h34; mul_ref[17] = 8'h20;
    a_vec[18] = 8'h90; b_vec[18] = 8'h0B; add_ref[18] = 8'h00; mul_ref[18] = 8'h00;
    a_vec[19] = 8'h3F; b_vec[19] = 8'h3F; add_ref[19] = 8'h47; mul_ref[19] = 8'h40;

    for (int i = 0; i < N; i++) begin
      logic [7:0] a, b, got_add, got_mul;
      a = a_vec[i]; b = b_vec[i];
      got_add = fp8_add(a, b);
      got_mul = fp8_mul(a, b);
      if (got_add !== add_ref[i] || got_mul !== mul_ref[i]) begin
        $display("FAIL case %0d: a=%02h b=%02h got add=%02h mul=%02h exp add=%02h mul=%02h",
                 i, a, b, got_add, got_mul, add_ref[i], mul_ref[i]);
        fails++;
      end
    end

    if (fails == 0) begin
      $display("tb_fp8 PASSED (%0d/%0d)", N, N);
    end else begin
      $display("tb_fp8 FAILED (%0d failures)", fails);
    end
    $finish;
  end
endmodule